from pathlib import Path

index_path = Path('index.html')
smoke_path = Path('.github/workflows/smoke-test.yml')

# Safety rule: always read the complete current file from the checked-out main
# immediately before applying the narrow replacement.
s = index_path.read_text(encoding='utf-8')
smoke = smoke_path.read_text(encoding='utf-8')

start_marker = 'function kaspiAdsBreakdown('
end_marker = 'function setReportPeriod('
if s.count(start_marker) != 1 or s.count(end_marker) != 1:
    raise SystemExit('Kaspi ads patch markers are not unique')
start = s.index(start_marker)
end = s.index(end_marker, start)

new_block = r'''function kaspiAdsIsoDate(value){if(value instanceof Date&&!Number.isNaN(value.getTime())){const y=value.getFullYear(),m=String(value.getMonth()+1).padStart(2,'0'),d=String(value.getDate()).padStart(2,'0');return `${y}-${m}-${d}`}if(typeof value==='number'&&Number.isFinite(value)){if(value>20000&&value<80000){const d=new Date(Math.round((value-25569)*86400000));return d.toISOString().slice(0,10)}const d=new Date(value);if(!Number.isNaN(d.getTime()))return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}const x=String(value??'').trim();if(!x)return '';let m=x.match(/^(20\d{2})[-\/.](\d{1,2})[-\/.](\d{1,2})/);if(m)return `${m[1]}-${String(m[2]).padStart(2,'0')}-${String(m[3]).padStart(2,'0')}`;m=x.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](20\d{2})/);if(m)return `${m[3]}-${String(m[2]).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`;return ''}
function kaspiAdsSourceKey(fileName){let x=String(fileName||'Kaspi Marketing').replace(/\.[^.]+$/,'').toLowerCase().replace(/\s*\(\d+\)\s*$/,'').replace(/20\d{2}[-_.]\d{1,2}[-_.]\d{1,2}/g,' ').replace(/\d{1,2}[-_.]\d{1,2}[-_.]20\d{2}/g,' ').replace(/\s+/g,' ').trim();return x||'kaspi marketing'}
function kaspiAdsMatchProduct(line){if(line?.productId){const p=prod(line.productId);if(p)return p}const sku=String(line?.sku||'').trim(),name=String(line?.name||'').trim();if(sku){const p=state.products.find(x=>adsSkuEqual(x.kaspi,sku));if(p)return p}if(name){const nn=normalizeName(name),p=state.products.find(x=>normalizeName(x.name)===nn);if(p)return p}return null}
function kaspiAdsBreakdown(days=reportPeriod){const start=reportPeriodStart(days),end=reportPeriodEnd(),byProduct=new Map();let total=0,unmatched=0,skippedLegacy=0,skippedLegacyAmount=0;for(const batch of(state.kaspiAdExpenses||[])){if(Array.isArray(batch.lines)&&batch.lines.length){for(const line of batch.lines){const ts=orderDayStart(line.date),amount=Math.max(0,Number(line.amount)||0);if(ts===null||ts<start||ts>=end||!(amount>0))continue;total+=amount;const p=kaspiAdsMatchProduct(line);if(p)byProduct.set(String(p.id),(byProduct.get(String(p.id))||0)+amount);else unmatched+=amount}continue}const bs=orderDayStart(batch.fromDate),last=orderDayStart(batch.toDate||batch.fromDate);if(bs===null||last===null)continue;const be=last+86400000,batchTotal=Math.max(0,Number(batch.amount)||0),overlap=Math.max(0,Math.min(end,be)-Math.max(start,bs));if(!overlap)continue;const exactDay=bs===last,fullyCovered=start<=bs&&end>=be;if(!exactDay&&!fullyCovered){skippedLegacy++;skippedLegacyAmount+=batchTotal;continue}total+=batchTotal;let mapped=0;for(const row of(batch.perProduct||[])){const amount=Math.max(0,Number(row.amount)||0),p=kaspiAdsMatchProduct(row);mapped+=amount;if(p)byProduct.set(String(p.id),(byProduct.get(String(p.id))||0)+amount)}unmatched+=Math.max(0,Number.isFinite(Number(batch.unmatchedAmount))?Number(batch.unmatchedAmount):batchTotal-mapped)}return {total,byProduct,unmatched,skippedLegacy,skippedLegacyAmount}}
function kaspiAdsForProduct(productId,days=reportPeriod){return kaspiAdsBreakdown(days).byProduct.get(String(productId))||0}
function renderKaspiAdsStatus(days=reportPeriod){const badge=document.getElementById('kaspiAdsBadge'),status=document.getElementById('kaspiAdsStatus');if(!badge||!status)return;const x=kaspiAdsBreakdown(days),count=(state.kaspiAdExpenses||[]).length;badge.textContent=fmt(x.total);badge.className='badge '+(x.total>0?'warn':'');const legacy=x.skippedLegacy?` · пропущено старых многодневных импортов без точной даты: ${x.skippedLegacy} (${fmt(x.skippedLegacyAmount)}) — переимпортируйте детальный отчёт`:'';status.textContent=count?`За выбранный период учтено ${fmt(x.total)} · импортов: ${count}${x.unmatched>0?' · без привязки к товару '+fmt(x.unmatched):''}${legacy}`:'Расходов ещё нет. Импортируйте детальный Excel-отчёт рекламной кампании Kaspi.'}
function loadXlsxLibrary(){if(window.XLSX)return Promise.resolve(window.XLSX);if(xlsxLoadPromise)return xlsxLoadPromise;xlsxLoadPromise=new Promise((resolve,reject)=>{const sc=document.createElement('script');sc.src='https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js';sc.async=true;sc.onload=()=>window.XLSX?resolve(window.XLSX):reject(new Error('Библиотека Excel не загрузилась'));sc.onerror=()=>reject(new Error('Не удалось загрузить обработчик Excel. Проверьте интернет.'));document.head.appendChild(sc)});return xlsxLoadPromise}
function openKaspiAdsImport(){const today=localDateInputValue();showSheet(`<h3>Реклама Kaspi · по товарам</h3><div class="link-note"><b>Обзорный отчёт не подходит.</b> Нужен детальный Excel из Kaspi Pay → Маркетинг → Реклама товаров → Мои кампании → конкретная кампания. В нём расход «Стоимость» должен относиться к конкретному товару. Если в файле есть колонка «Дата», приложение возьмёт дату каждой строки. Если даты в строках нет — выгружайте ровно один день и укажите этот день ниже. Многодневный расход без дат не распределяется между днями.</div><div class="two"><div class="field"><label>Дата от (резерв, если в файле нет даты)</label><input id="kaspiAdsFrom" type="date" value="${today}"></div><div class="field"><label>Дата до</label><input id="kaspiAdsTo" type="date" value="${today}"></div></div><div class="field"><label>Детальный Excel/CSV рекламной кампании</label><input id="kaspiAdsFile" type="file" accept=".xlsx,.xls,.csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel,text/csv"></div><button class="btn dark full" onclick="importKaspiAdsFile()">Импортировать расходы по товарам</button>`)}
async function kaspiAdsHash(buffer){try{if(!crypto?.subtle)return '';const digest=await crypto.subtle.digest('SHA-256',buffer.slice(0));return [...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('')}catch{return ''}}
async function kaspiAdsTextHash(text){try{const data=new TextEncoder().encode(String(text||''));return await kaspiAdsHash(data.buffer)}catch{return ''}}
async function importKaspiAdsFile(){const input=document.getElementById('kaspiAdsFile'),file=input?.files?.[0],fromDate=document.getElementById('kaspiAdsFrom')?.value||'',toDate=document.getElementById('kaspiAdsTo')?.value||'';if(!file)return alert('Выберите детальный Excel-отчёт Kaspi');const a=orderDayStart(fromDate),b=orderDayStart(toDate);if(a===null||b===null)return alert('Укажите дату отчёта');const fallbackFrom=a<=b?fromDate:toDate,fallbackTo=a<=b?toDate:fromDate;try{const buffer=await file.arrayBuffer(),XLSX=await loadXlsxLibrary(),workbook=XLSX.read(buffer,{type:'array',cellDates:true}),sheet=workbook.Sheets[workbook.SheetNames[0]],rows=XLSX.utils.sheet_to_json(sheet,{defval:'',raw:true});if(!rows.length)throw new Error('В файле нет строк');const headers=[...new Set(rows.flatMap(r=>Object.keys(r)))],normalized=headers.map(k=>[k,adsColumn(k)]);const costKey=(normalized.find(([,n])=>n==='стоимость')||normalized.find(([,n])=>/^стоимость\b/.test(n))||normalized.find(([,n])=>/расход.*реклам|затрат.*реклам|стоимост.*реклам/.test(n)))?.[0];if(!costKey)throw new Error('Не найден столбец «Стоимость». Нужен детальный отчёт рекламной кампании Kaspi.');const skuKey=(normalized.find(([,n])=>n==='sku'||n==='артикул')||normalized.find(([,n])=>/\bsku\b|артикул|код товара/.test(n)))?.[0]||'',nameKey=(normalized.find(([,n])=>/^наименование товара$|^название товара$|^товар$/.test(n))||normalized.find(([,n])=>/наименован.*товар|назван.*товар/.test(n)))?.[0]||'',dateKey=(normalized.find(([,n])=>n==='дата')||normalized.find(([,n])=>/^дата\b|^день\b|^date\b/.test(n)))?.[0]||'',campaignKey=(normalized.find(([,n])=>/кампан/.test(n)))?.[0]||'';if(!skuKey&&!nameKey)throw new Error('Обзорный отчёт не подходит: в нём нет SKU/артикула или названия товара. Скачайте Excel из конкретной рекламной кампании.');if(!dateKey&&fallbackFrom!==fallbackTo)throw new Error('В файле нет даты по строкам. Для точного учёта выгрузите один день и укажите одинаковую дату «от» и «до». Расход не будет распределён автоматически.');const sourceKey=kaspiAdsSourceKey(file.name),detail=[];let unidentified=0,used=0;for(const row of rows){const rowText=headers.map(k=>String(row[k]??'')).join(' ').trim();if(/(^|\s)(итого|всего|total)(\s|$)/i.test(rowText))continue;const amount=adsMoney(row[costKey]);if(!(amount>0))continue;const sku=skuKey?String(row[skuKey]??'').trim():'',name=nameKey?String(row[nameKey]??'').trim():'',campaign=campaignKey?String(row[campaignKey]??'').trim():'';if(!sku&&!name){unidentified+=amount;continue}let date=dateKey?kaspiAdsIsoDate(row[dateKey]):'';if(!date){if(fallbackFrom===fallbackTo)date=fallbackFrom;else throw new Error('Есть строки расхода без корректной даты. Выгрузите отчёт за один день либо файл с колонкой «Дата».')}const p=kaspiAdsMatchProduct({sku,name});detail.push({date,productId:p?.id||null,sku,name:p?.name||name,campaign,source:campaign||sourceKey,amount});used++}if(unidentified>0)throw new Error(`Есть рекламный расход ${fmt(unidentified)} без товара/SKU. Такой файл нельзя надёжно распределить по товарам.`);if(!detail.length)throw new Error('Не найдено строк с рекламным расходом по товарам');const grouped=new Map();for(const line of detail){const key=[line.date,line.source,String(line.sku||'').toLowerCase(),normalizeName(line.name),String(line.productId||'')].join('|');const old=grouped.get(key);if(old)old.amount+=line.amount;else grouped.set(key,{...line})}const lines=[...grouped.values()].sort((x,y)=>String(x.date).localeCompare(String(y.date))||String(x.source).localeCompare(String(y.source))||String(x.sku).localeCompare(String(y.sku))||String(x.name).localeCompare(String(y.name))),total=lines.reduce((n,x)=>n+(Number(x.amount)||0),0),dates=lines.map(x=>x.date).filter(Boolean).sort(),actualFrom=dates[0]||fallbackFrom,actualTo=dates[dates.length-1]||fallbackTo,canonical=lines.map(x=>[x.date,x.source,String(x.sku||'').trim().toLowerCase(),normalizeName(x.name),Math.round((Number(x.amount)||0)*100)/100]),detailHash=await kaspiAdsTextHash(JSON.stringify(canonical)),hash=await kaspiAdsHash(buffer);if((state.kaspiAdExpenses||[]).some(x=>(hash&&x.hash===hash)||(detailHash&&x.detailHash===detailHash)))return alert('Этот детальный отчёт уже импортирован. Повторный импорт заблокирован.');const perProductMap=new Map();let unmatchedAmount=0;for(const line of lines){const p=kaspiAdsMatchProduct(line);if(p){line.productId=p.id;const old=perProductMap.get(p.id)||{productId:p.id,sku:line.sku,name:p.name,amount:0};old.amount+=line.amount;perProductMap.set(p.id,old)}else unmatchedAmount+=line.amount}const batch={id:'ads-'+id(),market:'Kaspi',source:'Kaspi Marketing detail',sourceKey,fileName:file.name,hash,detailHash,fromDate:actualFrom,toDate:actualTo,amount:total,rowsCount:used,lines,perProduct:[...perProductMap.values()],unmatchedAmount,importedAt:Date.now()};state.kaspiAdExpenses.push(batch);save();closeModal();renderReports();alert(`Детальная реклама Kaspi импортирована.\nПериод: ${actualFrom} — ${actualTo}\nРасход: ${fmt(total)}\nСтрок по товарам: ${lines.length}\nПривязано: ${fmt(total-unmatchedAmount)}${unmatchedAmount>0?'\nБез привязки: '+fmt(unmatchedAmount):''}`)}catch(e){alert('Не удалось импортировать рекламу Kaspi:\n'+String(e.message||e))}}
function removeKaspiAdsBatch(batchId){const x=(state.kaspiAdExpenses||[]).find(b=>b.id===batchId);if(!x)return;if(!confirm(`Удалить импорт ${x.fileName||''} на ${fmt(x.amount)}?`))return;state.kaspiAdExpenses=(state.kaspiAdExpenses||[]).filter(b=>b.id!==batchId);save();renderReports();showKaspiAdsHistory()}
function showKaspiAdsHistory(){const rows=[...(state.kaspiAdExpenses||[])].sort((a,b)=>(Number(b.importedAt)||0)-(Number(a.importedAt)||0));const body=rows.length?rows.map(x=>{const detailed=Array.isArray(x.lines)&&x.lines.length;return `<div class="item" style="margin-top:8px"><div class="row"><div class="grow"><b>${esc(x.fileName||'Kaspi реклама')}</b><div class="muted">${esc(x.fromDate||'—')} — ${esc(x.toDate||x.fromDate||'—')} · ${detailed?x.lines.length:(x.rowsCount||0)} строк${detailed?' · точные даты':' · старый импорт без построчных дат'}</div><div class="muted">Без привязки при импорте: ${fmt(x.unmatchedAmount||0)}</div></div><div class="right"><b>${fmt(x.amount)}</b><button class="btn danger" style="display:block;margin-top:7px" onclick="removeKaspiAdsBatch('${x.id}')">Удалить</button></div></div></div>`}).join(''):'<div class="empty">Импортов рекламы пока нет</div>';showSheet(`<h3>Реклама Kaspi · история</h3>${body}<button class="btn dark full" onclick="openKaspiAdsImport()">Импортировать ещё</button>`)}
'''

s = s[:start] + new_block + s[end:]

# Extend the existing lifecycle/financial smoke contract so the exact-date rule
# cannot silently regress to proportional allocation again.
needle = "            'Реклама Kaspi без привязки','xlsx@0.18.5'\n"
replacement = "            'Реклама Kaspi без привязки','xlsx@0.18.5',\n            'function kaspiAdsIsoDate(','function kaspiAdsMatchProduct(',\n            'Обзорный отчёт не подходит','Многодневный расход без дат не распределяется между днями',\n            'detailHash','Array.isArray(batch.lines)'\n"
if smoke.count(needle) != 1:
    raise SystemExit('Smoke required-marker anchor changed')
smoke = smoke.replace(needle, replacement, 1)

ban_anchor = "          if 'price:Number(old?.price)||Number(o.unitPrice)||0' in html:\n              raise SystemExit('Marketplace reports prefer stale sale price over current D1 price')\n"
ban_replacement = ban_anchor + "          if 'factor=Math.min(1,overlap/span)' in html or 'расход распределится по дням этого периода равномерно' in html:\n              raise SystemExit('Kaspi ads must use exact product/date costs, never proportional spreading')\n"
if smoke.count(ban_anchor) != 1:
    raise SystemExit('Smoke proportional-allocation ban anchor changed')
smoke = smoke.replace(ban_anchor, ban_replacement, 1)

index_path.write_text(s, encoding='utf-8')
smoke_path.write_text(smoke, encoding='utf-8')
